bool isPalindrome(ListNode* head) {
    vector<int> values;
    for (ListNode* node = head; node; node = node->next) values.push_back(node->val);     // collect every value into a plain vector
    int left = 0, right = (int)values.size() - 1;
    while (left < right) {
        if (values[left] != values[right]) return false;                                    // compare the array against its own reverse using two pointers
        left++;
        right--;
    }
    return true;
}

int main() {
    ListNode* head = new ListNode(1, new ListNode(2, new ListNode(2, new ListNode(1))));
    cout << (isPalindrome(head) ? "true" : "false") << endl;
    return 0;
}

