import java.util.*;

public class Main {
    boolean isPalindrome(ListNode head) {
        ListNode slow = head;
        ListNode fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;                                                     // find the middle using the classic slow/fast technique
            fast = fast.next.next;
        }

        ListNode prev = null;
        ListNode curr = slow;
        while (curr != null) {
            ListNode next = curr.next;
            curr.next = prev;                                                       // reverse the second half of the list in place
            prev = curr;
            curr = next;
        }

        ListNode first = head, second = prev;
        while (second != null) {                                                    // walk both halves together, comparing values
            if (first.val != second.val) return false;
            first = first.next;
            second = second.next;
        }
        return true;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        ListNode head = new ListNode(1, new ListNode(2, new ListNode(2, new ListNode(1))));
        System.out.println(solution.isPalindrome(head));
    }
}

